&lt;ul&gt;&lt;li&gt;&lt;b&gt;Taille&lt;/b&gt; P&lt;/li&gt;&lt;li&gt;&lt;b&gt;Vitesse&lt;/b&gt; 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) escalade 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque&lt;/b&gt; morsure (1d4 plus poison)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque sp&#233;ciale&lt;/b&gt; poison (&lt;i&gt;Fr&#233;quence&lt;/i&gt; 1 round (6), &lt;i&gt;Effet&lt;/i&gt; affaiblissement temporaire 1 &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;For&lt;/a&gt;, &lt;i&gt;Gu&#233;rison&lt;/i&gt; 1 jet de sauvegarde, &lt;i&gt;DD&lt;/i&gt; d&#233;pendant de la &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Constitution&lt;/a&gt;)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;s&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Perception-Des-Vibrations-(Capacit&#233;).html&quot; title=&quot;Perception des vibrations&quot;&gt;perception des vibrations&lt;/a&gt; &#224; 9 m (6 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt; DMD&lt;/b&gt; croc-en-jambe +12&lt;/li&gt;&lt;li&gt;&lt;b&gt;Caract&#233;ristiques&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;For&lt;/a&gt; 6, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dex&lt;/a&gt; 17, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Con&lt;/a&gt; 10, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Int&lt;/a&gt; –, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sag&lt;/a&gt; 10, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Cha&lt;/a&gt; 2&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA&lt;/b&gt; armure naturelle +0&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;veloppement au niveau 4&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Taille&lt;/b&gt; M&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA&lt;/b&gt; armure naturelle +1&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque&lt;/b&gt; morsure (1d6 plus poison)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Caract&#233;ristiques&lt;/b&gt; For +4, Dex -2, Con +2&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a name=&quot;Col&#233;opt&#232;reg&#233;ant&quot;&gt;&lt;/a&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Col&#233;opt&#232;re g&#233;ant&lt;div style=&quot;float:right;&quot;&gt;&lt;/div&gt;&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Source&lt;/b&gt; Bestiaire, p.49&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Caract&#233;ristiques de d&#233;part&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Taille&lt;/b&gt; P&lt;/li&gt;&lt;li&gt;&lt;b&gt;Vitesse&lt;/b&gt; 6 m (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;), vol 6 m (4 &lt;abbr title=&quot;cases&quot;&gt;c&lt;/abbr&gt;) (m&#233;diocre)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque&lt;/b&gt; morsure (1d6)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Vision-Dans-Le-Noir-(Capacit&#233;).html&quot; title=&quot;vision dans le noir&quot;&gt;vision dans le noir&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;DMD&lt;/b&gt; croc-en-jambe +8&lt;/li&gt;&lt;li&gt;&lt;b&gt;Caract&#233;ristiques&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Force.html&quot; title=&quot;La Force&quot;&gt;For&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Dexterite.html&quot; title=&quot;La Dext&#233;rit&#233;&quot;&gt;Dex&lt;/a&gt; 12, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Constitution.html&quot; title=&quot;La Constitution&quot;&gt;Con&lt;/a&gt; 13, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Intelligence.html&quot; title=&quot;L&amp;#39;Intelligence&quot;&gt;Int&lt;/a&gt; –, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Sagesse.html&quot; title=&quot;La Sagesse&quot;&gt;Sag&lt;/a&gt; 11, &lt;a class=&quot;pagelink&quot; href=&quot;Caract&#233;ristiques#Charisme.html&quot; title=&quot;Le Charisme&quot;&gt;Cha&lt;/a&gt; 4&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA&lt;/b&gt; armure naturelle +6&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;veloppement au niveau 4&lt;/div&gt;
&lt;ul&gt;&lt;li&gt;&lt;b&gt;Taille&lt;/b&gt; M&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque&lt;/b&gt; morsure (1d8)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaque sp&#233;ciale&lt;/b&gt; &lt;a class=&quot;pagelink&quot; href=&quot;Pi&#233;tinement.html&quot; title=&quot;Pi&#233;tinement&quot;&gt;pi&#233;tinement&lt;/a&gt; (1d4)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Caract&#233;ristiques&lt;/b&gt; For +4, Dex -2, Con +2&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;div class=&quot;BD&quot;&gt;&lt;br /&gt;&lt;br /&gt;&lt;a name=&quot;Crabeg&#233;ant&quot;&gt;&lt;/a&gt;
